func isSQLiteBusy(err error) bool {
  if err == nil {
    return false
  }
  text := strings.ToLower(err.Error())
  return strings.Contains(text, "sqlite_busy") ||
    strings.Contains(text, "database is locked") ||
    strings.Contains(text, "database table is locked")
}

